  <script>
    // Mobile menu toggle
    document.getElementById('mobile-menu-btn').addEventListener('click', function() {
      document.getElementById('mobile-menu').classList.toggle('hidden');
    });

    // Instructor data
    const instructors = [
      { name: 'Dani Reyes', location: 'new-york', city: 'New York', image: 'https://images.unsplash.com/photo-1594381898411-846e7d193883?w=400&q=80', specialty: 'HIIT & Strength' },
      { name: 'Marcus Cole', location: 'los-angeles', city: 'Los Angeles', image: 'https://images.unsplash.com/photo-1567013127542-490d757e51fc?w=400&q=80', specialty: 'Cardio & Conditioning' },
      { name: 'Priya Nair', location: 'london', city: 'London', image: 'https://images.unsplash.com/photo-1571019613454-1cb2f99b2d8b?w=400&q=80', specialty: 'Full Body HIIT' },
      { name: 'Jordan Voss', location: 'miami', city: 'Miami', image: 'https://images.unsplash.com/photo-1597347316205-36f6c451902a?w=400&q=80', specialty: 'Strength & Power' },
      { name: 'Tessa Kim', location: 'san-francisco', city: 'San Francisco', image: 'https://images.unsplash.com/photo-1609899464726-209befaac5ba?w=400&q=80', specialty: 'Cardio Endurance' },
      { name: 'Andre Williams', location: 'new-york', city: 'New York', image: 'https://images.unsplash.com/photo-1583468982228-19f19164aee2?w=400&q=80', specialty: 'HIIT & Conditioning' },
      { name: 'Sofia Marquez', location: 'los-angeles', city: 'Los Angeles', image: 'https://images.unsplash.com/photo-1591228376774-5706d4c4c5d6?w=400&q=80', specialty: 'Strength Training' },
      { name: 'Liam Chen', location: 'london', city: 'London', image: 'https://images.unsplash.com/photo-1583454110551-21f2fa2afe61?w=400&q=80', specialty: 'Functional Fitness' },
      { name: 'Elena Petrova', location: 'miami', city: 'Miami', image: 'https://images.unsplash.com/photo-1599827579079-73f84d62fc35?w=400&q=80', specialty: 'HIIT & Cardio' },
      { name: 'James Okonkwo', location: 'san-francisco', city: 'San Francisco', image: 'https://images.unsplash.com/photo-1583454155184-870a1f63be09?w=400&q=80', specialty: 'Athletic Performance' },
      { name: 'Mia Johansson', location: 'new-york', city: 'New York', image: 'https://images.unsplash.com/photo-1548690312-e3b507d8c110?w=400&q=80', specialty: 'Core & Strength' },
      { name: 'Carlos Rivera', location: 'los-angeles', city: 'Los Angeles', image: 'https://images.unsplash.com/photo-1517838277536-f5f99be501cd?w=400&q=80', specialty: 'High Intensity' }
    ];

    const grid = document.getElementById('instructor-grid');
    const noResults = document.getElementById('no-results');
    let currentFilter = 'all';

    function renderInstructors(filter) {
      grid.innerHTML = '';
      const filtered = filter === 'all' ? instructors : instructors.filter(i => i.location === filter);

      if (filtered.length === 0) {
        noResults.classList.remove('hidden');
      } else {
        noResults.classList.add('hidden');
        filtered.forEach(instructor => {
          const card = document.createElement('div');
          card.className = 'bg-redroom-gray border border-gray-800 hover:border-redroom-red transition-all group';
          card.innerHTML = `
            <div class="relative overflow-hidden">
              <img src="${instructor.image}" alt="${instructor.name}" class="w-full h-[250px] object-cover group-hover:scale-105 transition-transform duration-300">
              <div class="absolute inset-0 bg-gradient-to-t from-redroom-charcoal/80 to-transparent"></div>
            </div>
            <div class="p-5">
              <h3 class="font-display text-2xl mb-1">${instructor.name}</h3>
              <p class="text-redroom-red text-sm font-semibold mb-2">${instructor.city}</p>
              <p class="text-gray-400 text-sm mb-4">${instructor.specialty}</p>
              <a href="#" class="inline-block w-full text-center bg-redroom-red hover:bg-red-600 text-white font-semibold py-2 tracking-wider transition-colors text-sm">BOOK A CLASS</a>
            </div>
          `;
          grid.appendChild(card);
        });
      }
    }

    // Filter buttons
    document.querySelectorAll('[data-location]').forEach(btn => {
      btn.addEventListener('click', () => {
        currentFilter = btn.dataset.location;
        document.querySelectorAll('[data-location]').forEach(b => {
          b.classList.remove('bg-redroom-red', 'text-white');
          b.classList.add('bg-redroom-gray', 'text-gray-300');
        });
        btn.classList.add('bg-redroom-red', 'text-white');
        btn.classList.remove('bg-redroom-gray', 'text-gray-300');
        renderInstructors(currentFilter);
      });
    });

    // Initial render
    renderInstructors('all');

    // Newsletter form
    document.getElementById('newsletter-form').addEventListener('submit', function(e) {
      e.preventDefault();
      const email = document.getElementById('newsletter-email').value;
      const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
      const successEl = document.getElementById('newsletter-success');
      const errorEl = document.getElementById('newsletter-error');

      successEl.classList.add('hidden');
      errorEl.classList.add('hidden');

      if (emailRegex.test(email)) {
        successEl.classList.remove('hidden');
        document.getElementById('newsletter-email').value = '';
      } else {
        errorEl.classList.remove('hidden');
      }
    });
  </script>
